class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + Number : int
}

class Bed {
  + Category : string
  + Price : double
}

class Inhabitant {
  + Name : string
  + RegistrationDate : date
}

class StayCategory {
  + Type : string
  + Price : double
}

class RegistrationProcess {
  + Questions : list[string]
}

class Assessment {
  + Needs : map[string, int]
  + RecommendedStay : StayCategory
}

class WaitingList {
  + Position : int
}

class Proposal {
  + Date : date
  + Accepted : boolean
}

class Invoice {
  + Number : int
  + Total : double
  + OutstandingAmount : double
  + Status : string
}

class PaymentEvent {}

